snippet.body:
-*- template; template-run;
\version "$LILYPOND_VERSION"

\layout {
  indent = 0
}

\header {
  title = "Title"
  subtitle = "subtitle"
  composer = "composer"
  arranger = "arranger"
  enteredby = "HeitorJr"
  tagline = ##f
  % tagline = "github.com/my-not-so-important-repos/estudos-lilypond"
}

#(set-global-staff-size 35)

\paper {
  % kindle|kobo friendly
  #(set-paper-size "a5landscape" )
  %#(set-paper-size "a5" 'landscape )
}

global = {
  \time 4/4
  \numericTimeSignature
  \key c \major
  \tempo 4=100
  \easyHeadsOn
}

chordNames = \chordmode {
  \global
  c1

}

melody = \relative c'' {
  \global
  c4 d e f
  $CURSOR
}

words = \lyricmode {
  la la la

}

\score {
  <<
    \new ChordNames \chordNames
    %\new FretBoards \chordNames
    \new Staff { \melody }
    \addlyrics { \words }
  >>
  \layout { }
  \midi { }
}
